<script lang="ts">import { onMount } from 'svelte'; import { base } from '$app/paths'; import { acceptEffort, completeEffort, initialEffortState, type EffortState } from '$lib/efforts/contracts'; let state: EffortState = initialEffortState(); let message = 'Choose one public War Effort.'; onMount(() => { const p = new URLSearchParams(location.search); if (p.get('accept')) state = acceptEffort(state, p.get('accept')!); if (p.get('complete')) { state = completeEffort({ ...state, active: p.get('complete') }, 3); message = 'War Effort completed; reward paid.'; } });</script>
<main><section><h1>War Efforts</h1><p>Public contracts · one active effort · visible rewards.</p>{#each state.row as effort}<article><h2>{effort.name}</h2><p>Cost {effort.cost} · Reward {effort.reward} Renown</p><a href={`${base}/efforts/?accept=${effort.id}`} data-sveltekit-reload>Accept</a>{#if state.active === effort.id}<a href={`${base}/efforts/?complete=${effort.id}`} data-sveltekit-reload>Complete</a>{/if}</article>{/each}<p role="status">{message} Active: {state.active ?? 'none'} · Renown: {state.renown}</p></section></main>
<style>:global(body){margin:0;background:#17251f;font-family:system-ui}main{min-height:100vh;padding:2rem}section{max-width:60rem;margin:5vh auto;padding:3rem;background:#f6efda;color:#20261f}article{padding:1rem;margin:1rem 0;background:#e7ddc5}a{display:inline-block;padding:.7rem 1rem;margin-right:.5rem;background:#6d452d;color:white;text-decoration:none;border-radius:.4rem;font-weight:700}</style>
